import 'package:flutter/foundation.dart';
import '../../integrations/ai/quiz_port.dart';

/// Curriculum labels and count limits supplied by an approved Dataset/service
/// adapter, never guessed from the prototype or generated by a Widget.
class QuizUnit {
  const QuizUnit({
    required this.id,
    required this.arabicName,
    required this.englishName,
  });
  final String id, arabicName, englishName;
}

class QuizSubject {
  QuizSubject({
    required this.id,
    required this.arabicName,
    required this.englishName,
    required Iterable<QuizUnit> units,
  }) : units = List.unmodifiable(units);
  final String id, arabicName, englishName;
  final List<QuizUnit> units;
}

class QuizCurriculumSnapshot {
  QuizCurriculumSnapshot({
    required this.catalogId,
    required this.datasetRevision,
    required Iterable<QuizSubject> subjects,
    required Map<QuizQuestionType, List<int>> allowedCounts,
  }) : subjects = List.unmodifiable(subjects),
       allowedCounts = Map.unmodifiable(
         allowedCounts.map(
           (type, counts) => MapEntry(type, List<int>.unmodifiable(counts)),
         ),
       );
  final String catalogId, datasetRevision;
  final List<QuizSubject> subjects;
  final Map<QuizQuestionType, List<int>> allowedCounts;
  bool get isWellFormed {
    bool text(String s) =>
        s.trim().isNotEmpty &&
        s == s.trim() &&
        s.length <= 512 &&
        !RegExp(r'[\x00-\x1f]').hasMatch(s);
    return text(catalogId) &&
        text(datasetRevision) &&
        subjects.isNotEmpty &&
        subjects.length <= 64 &&
        subjects.map((s) => s.id).toSet().length == subjects.length &&
        subjects.every(
          (s) =>
              text(s.id) &&
              text(s.arabicName) &&
              text(s.englishName) &&
              s.units.isNotEmpty &&
              s.units.length <= 512 &&
              s.units.map((u) => u.id).toSet().length == s.units.length &&
              s.units.every(
                (u) => text(u.id) && text(u.arabicName) && text(u.englishName),
              ),
        ) &&
        QuizQuestionType.values.every((type) {
          final counts = allowedCounts[type];
          return counts != null &&
              counts.isNotEmpty &&
              counts.length <= 128 &&
              counts.toSet().length == counts.length &&
              counts.every((n) => n > 0);
        });
  }
}

abstract interface class QuizCurriculumPort {
  Future<QuizCurriculumSnapshot?> read();
}

class UnavailableQuizCurriculum implements QuizCurriculumPort {
  const UnavailableQuizCurriculum();
  @override
  Future<QuizCurriculumSnapshot?> read() async => null;
}

class QuizSelection {
  const QuizSelection({
    required this.catalog,
    required this.scope,
    required this.type,
    required this.count,
  });
  final QuizCurriculumSnapshot catalog;
  final QuizScope scope;
  final QuizQuestionType type;
  final int count;
  bool get isValid =>
      catalog.isWellFormed &&
      catalog.subjects.any(
        (s) =>
            s.id == scope.subjectId && s.units.any((u) => u.id == scope.unitId),
      ) &&
      (catalog.allowedCounts[type]?.contains(count) ?? false);
}

class QuizSetupController extends ChangeNotifier {
  QuizSetupController({
    required QuizCurriculumPort catalog,
    required QuizAvailability Function() availability,
  }) : _catalog = catalog,
       _availability = availability;
  final QuizCurriculumPort _catalog;
  final QuizAvailability Function() _availability;
  QuizCurriculumSnapshot? snapshot;
  String? subjectId, unitId;
  QuizQuestionType type = QuizQuestionType.mcq;
  int? count;
  bool loading = false, failed = false, _disposed = false;
  int _generation = 0;
  bool get resourcesReady =>
      _availability().isReady &&
      _availability().datasetRevision == snapshot?.datasetRevision;
  QuizSelection? get selection {
    final data = snapshot, subject = subjectId, unit = unitId, n = count;
    if (data == null || subject == null || unit == null || n == null) {
      return null;
    }
    final value = QuizSelection(
      catalog: data,
      scope: QuizScope(subjectId: subject, unitId: unit),
      type: type,
      count: n,
    );
    return value.isValid ? value : null;
  }

  bool get canStart => !loading && resourcesReady && selection != null;
  Future<void> load() async {
    final generation = ++_generation;
    loading = true;
    failed = false;
    _notify();
    try {
      final value = await _catalog.read();
      if (_disposed || generation != _generation) return;
      snapshot = value?.isWellFormed == true ? value : null;
      failed = value != null && snapshot == null;
      subjectId = null;
      unitId = null;
      count = snapshot?.allowedCounts[type]?.first;
    } catch (_) {
      if (!_disposed && generation == _generation) {
        snapshot = null;
        failed = true;
      }
    } finally {
      if (!_disposed && generation == _generation) {
        loading = false;
        _notify();
      }
    }
  }

  void selectSubject(String? value) {
    if (_disposed) return;
    subjectId = snapshot?.subjects.any((s) => s.id == value) == true
        ? value
        : null;
    unitId = null;
    _notify();
  }

  void selectUnit(String? value) {
    if (_disposed) return;
    final subjects = snapshot?.subjects.where((s) => s.id == subjectId);
    unitId =
        subjects?.isNotEmpty == true &&
            subjects!.first.units.any((u) => u.id == value)
        ? value
        : null;
    _notify();
  }

  void selectType(QuizQuestionType value) {
    if (_disposed) return;
    type = value;
    count = snapshot?.allowedCounts[type]?.first;
    _notify();
  }

  void selectCount(int? value) {
    if (_disposed) return;
    count = snapshot?.allowedCounts[type]?.contains(value) == true
        ? value
        : null;
    _notify();
  }

  void _notify() {
    if (!_disposed) notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    _generation++;
    super.dispose();
  }
}
